<template><div class="page-card" v-loading="loading"><div class="detail-toolbar"><el-button :icon="ArrowLeft" @click="router.push('/receivables')">返回应收账款</el-button><el-button v-if="row&&remain>0" type="primary" @click="router.push(`/payments/new?receivableId=${row.id}`)">登记收款</el-button></div><template v-if="row"><header class="bill-head"><div><span>应收账单</span><h1>{{row.contractCode}} / {{row.year}} 年</h1><p>{{row.merchantName}} · {{row.billboardCode}}</p></div><el-tag :type="statusTagType(row.status)" size="large">{{row.status}}</el-tag></header><div class="bill-amount"><div><span>应收金额</span><strong>¥ {{fmtMoney(row.amount)}}</strong></div><div><span>已收金额</span><strong class="green">¥ {{fmtMoney(row.received)}}</strong></div><div><span>剩余欠款</span><strong class="red">¥ {{fmtMoney(remain)}}</strong></div></div><section class="bill-section"><h2>账单关联信息</h2><el-descriptions :column="2" border><el-descriptions-item label="客户">{{row.merchantName}}</el-descriptions-item><el-descriptions-item label="合同编号">{{row.contractCode}}</el-descriptions-item><el-descriptions-item label="广告牌">{{row.billboardCode}}</el-descriptions-item><el-descriptions-item label="所属路段">{{row.sectionName}}</el-descriptions-item><el-descriptions-item label="应收年度">{{row.year}} 年</el-descriptions-item><el-descriptions-item label="核销状态">{{row.status}}</el-descriptions-item></el-descriptions></section><el-alert type="info" :closable="false" show-icon title="该账单由生效合同按“年度 × 广告牌”自动生成。收款后同步冲减应收并形成资金流水。"/></template><el-empty v-else-if="!loading" description="未找到应收账单"/></div></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{ArrowLeft}from'@element-plus/icons-vue';import{receivableApi}from'../api';import{fmtMoney,statusTagType}from'../utils/format';import type{Receivable}from'../types';const route=useRoute(),router=useRouter(),loading=ref(false),row=ref<Receivable|null>(null),remain=computed(()=>row.value?row.value.amount-row.value.received:0);onMounted(async()=>{loading.value=true;try{const id=Number(route.params.id);row.value=(await receivableApi.list({})).find(item=>item.id===id)||null}finally{loading.value=false}});
</script>
<style scoped>.detail-toolbar{display:flex;justify-content:space-between;margin-bottom:14px}.bill-head{display:flex;justify-content:space-between;align-items:center;padding:21px 24px;border:1px solid #cdd9e7;background:#f5f8fc}.bill-head span{color:#7d8998;font-size:12px}.bill-head h1{margin:5px 0;color:#173b64;font-size:22px}.bill-head p{color:#728095}.bill-amount{display:grid;grid-template-columns:repeat(3,1fr);border:1px solid #d8e1eb;border-top:0}.bill-amount div{padding:18px 22px;border-right:1px solid #e1e7ef}.bill-amount div:last-child{border:0}.bill-amount span,.bill-amount strong{display:block}.bill-amount span{color:#7b8797;font-size:12px}.bill-amount strong{margin-top:6px;color:#16488a;font-size:23px}.green{color:#3c8c5a!important}.red{color:#c84040!important}.bill-section{margin:22px 0}.bill-section h2{margin-bottom:12px;color:#25384e;font-size:16px}</style>

